"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[2456],{76164:e=>{e.exports=JSON.parse('{"functions":[{"name":"CreateNumberTween","desc":"Returns an unplayed [Tween] that animates `textLabel` from `start` to `goal`.\\n\\nThe label is written once immediately with the starting value, then updated on\\nevery step. The tween is not started \u2014 call `:Play()` yourself.\\n\\nValues are floored to integers unless `integer` is explicitly `false`, so a\\ncounter does not flicker through fractions. The connection driving the label lives\\nas long as the underlying NumberValue does, which is until the returned tween is\\ndropped.\\n\\n```lua\\nlocal tween = CreateNumberTween(\\n\\toldCoins,\\n\\tnewCoins,\\n\\tTweenInfo.new(0.8),\\n\\tcoinLabel,\\n\\ttrue,\\n\\t\\"%s coins\\"\\n)\\ntween:Play()\\n```","params":[{"name":"start","desc":"Starting value (defaults to 0)","lua_type":"number?"},{"name":"goal","desc":"Value to count to","lua_type":"number"},{"name":"tweenInfo","desc":"Falls back to a 1.2s linear tween when nil","lua_type":"TweenInfo"},{"name":"textLabel","desc":"Label whose `Text` is written each step","lua_type":"TextLabel"},{"name":"integer","desc":"Floor each step; defaults to true","lua_type":"boolean?"},{"name":"template","desc":"`string.format` pattern applied to the formatted number","lua_type":"string?"}],"returns":[{"desc":"","lua_type":"Tween"}],"function_type":"static","source":{"line":52,"path":"src/Shared/Class/CreateNumberTween.luau"}}],"properties":[],"types":[],"name":"CreateNumberTween","desc":"Counts a [TextLabel] up or down to a new number, formatting each step.\\n\\nBuilt on [CreateTween] \u2014 this adds the label binding, thousands separators via\\n`Util.formatNumber`, and optional rounding and templating.\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/survival-islands - proprietary and confidential.","source":{"line":12,"path":"src/Shared/Class/CreateNumberTween.luau"}}')}}]);